      "location": "line start, 1880",
      "fact": "The line begins at the lowest visible value on the chart, near the 1,000 gridline."
    },
    {
      "location": "line end, 1891",
      "fact": "The line ends at the highest visible value on the chart, near the 3,000 gridline."
    },
    {
      "location": "mid-section, 1886",
      "fact": "The line shows a local dip around 1886, sitting below the 1885 and 1887 points but above the 1880–1883 points."
    },
    {
      "location": "peak, 1890",
      "fact": "The highest point on the line is at 1890, near 3,300; the 1891 point is slightly lower but still the second-highest."
    }
  ],
  "printed_facts": [
    {
      "location": "y-axis label",
      "fact": "'Number of Tourists' with ticks 0, 500, 1,000, 1,500, 2,000, 2,500, 3,000, 3,500."
